package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MathInternalError;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.MathInternalError;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Test class for BaseSecantSolver.doSolve.
 * Since doSolve is protected, we use a Testable subclass to expose it.
 */
public class BaseSecantSolver_doSolve_TriageGen1Test {

    // Mocking the dependencies and the class structure via inheritance
    private static class TestableSecantSolver extends BaseSecantSolver {
        private UnivariateRealFunction function;
        private double min;
        private double max;
        private double ftol;
        private double atol;
        private double rtol;
        private AllowedSolution allowed;
        private Method method;

        public TestableSecantSolver(double rtol, double atol, double ftol, Method method, AllowedSolution allowed) {
            super(rtol, atol, ftol, method);
            this.rtol = rtol;
            this.atol = atol;
            this.ftol = ftol;
            this.method = method;
            this.allowed = allowed;
        }

        // Overriding to provide controlled values for the protected method doSolve
        @Override
        protected double getMin() { return min; }
        @Override
        protected double getMax() { return max; }
        @Override
        protected double computeObjectiveValue(double x) { return function.value(x); }
        @Override
        protected void verifyBracketing(double x0, double x1) {
            if (function.value(x0) * function.value(x1) > 0) {
                throw new IllegalArgumentException("Not bracketed");
            }
        }
        @Override
        protected double getFunctionValueAccuracy() { return ftol; }
        @Override
        protected double getAbsoluteAccuracy() { return atol; }
        @Override
        protected double getRelativeAccuracy() { return rtol; }

        // Expose doSolve via a public method for testing
        public double testDoSolve() {
            return doSolve();
        }

        public void setFunction(UnivariateRealFunction f) { this.function = f; }
        public void setBounds(double min, double max) { this.min = min; this.max = max; }
    }

    // Enum/Class stubs to match the provided context if not fully visible in scope
    // Assuming standard Apache Commons Math enums/classes
    enum Method { ILLINOIS, PEGASUS }
    enum AllowedSolution { ANY_SIDE, LEFT_SIDE, RIGHT_SIDE, BELOW_SIDE, ABOVE_SIDE }

    @Test
    public void testExactRootAtMin() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(2.0, 5.0);
        assertEquals(2.0, solver.testDoSolve(), 1e-15);
    }

    @Test
    public void testExactRootAtMax() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 5.0);
        solver.setBounds(2.0, 5.0);
        assertEquals(5.0, solver.testDoSolve(), 1e-15);
    }

    @Test
    public void testExactRootInIteration() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 3.0);
        solver.setBounds(2.0, 5.0);
        assertEquals(3.0, solver.testDoSolve(), 1e-15);
    }

    @Test
    public void testIllinoisMethodConvergence() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> Math.pow(x, 3) - 8); // root at 2
        solver.setBounds(1.0, 3.0);
        assertEquals(2.0, solver.testDoSolve(), 1e-7);
    }

    @Test
    public void testPegasusMethodConvergence() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.PEGASUS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> Math.pow(x, 3) - 8);
        solver.setBounds(1.0, 3.0);
        assertEquals(2.0, solver.testDoSolve(), 1e-7);
    }

    @Test
    public void testFtolConvergence_AnySide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        // Should exit when |f(x)| <= 0.1
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 0.2); 
    }

    @Test
    public void testFtolConvergence_LeftSide() {
        // Force inversion: x1 becomes the new x0
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.LEFT_SIDE);
        solver.setFunction(x -> 2.0 - x); // f(1)=1, f(3)=-1. Root is 2.
        solver.setBounds(1.0, 3.0);
        // If inverted, return x1
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 0.2);
    }

    @Test
    public void testFtolConvergence_RightSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.RIGHT_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        // If not inverted, return x1
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 0.2);
    }

    @Test
    public void testFtolConvergence_BelowSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.BELOW_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        // f(x1) should be <= 0
        // For x-2, if f(x) is small, x is near 2.
        assertEquals(2.0, result, 0.2);
    }

    @Test
    public void testFtolConvergence_AboveSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.ABOVE_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        // f(x1) should be >= 0
        assertEquals(2.0, result, 0.2);
    }

    @Test
    public void testAccuracyConvergence_LeftSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-5, 1e-5, 1e-10, Method.ILLINOIS, AllowedSolution.LEFT_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 1e-3);
    }

    @Test
    public void testAccuracyConvergence_RightSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-5, 1e-5, 1e-10, Method.ILLINOIS, AllowedSolution.RIGHT_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 1e-3);
    }

    @Test
    public void testAccuracyConvergence_BelowSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-5, 1e-5, 1e-10, Method.ILLINOIS, AllowedSolution.BELOW_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        // f(x) = x-2. If x=1.999, f(x) < 0.
        // The logic returns x1 if f1 <= 0, else x0.
        assertEquals(2.0, result, 1e-3);
    }

    @Test
    public void testAccuracyConvergence_AboveSide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-5, 1e-5, 1e-10, Method.ILLINOIS, AllowedSolution.ABOVE_SIDE);
        solver.setFunction(x -> x - 2.0);
        solver.setBounds(1.0, 3.0);
        double result = solver.testDoSolve();
        assertEquals(2.0, result, 1e-3);
    }
}
